/* Uyghur Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aynur": "moonlight — Turkic ay (moon) + Arabic nur (light)", "Erkin": "free, independent — Turkic", "Alim": "scholar, learned — Arabic", "Adil": "just, fair — Arabic", "Reyhangul": "basil flower — Persian reyhan (basil) + Turkic gul (flower)", "Meryem": "The Uyghur form of Mary, widely used.", "Kadeer": "Family name of Rebiya Kadeer; Uyghur surnames are traditionally patronymics.", "Isa": "Family name of Dolkun Isa, from the given name Isa.", "Tohti": "Family name of Ilham Tohti, from the given name Tohti.", "Hoshur": "Family name of journalist Shohret Hoshur."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aynur';
console.log(lookup(q));

